# A versioned pack is added once to existing databases. Original seed IDs stay stable.
import json
from pathlib import Path
from seed_pack import expansion

MEDIA = json.loads((Path(__file__).resolve().parent / 'static/media/credits.json').read_text('utf-8'))
for question in expansion():
    image_key = question.pop('image_key')
    question['image'] = {k: MEDIA[image_key][k] for k in
                         ('path', 'credit', 'license', 'source_url', 'license_url', 'changes')} if image_key else None
    question['pack_version'] = 4
    QUESTIONS.append(question)

from seed_more import expand_minimum
QUESTIONS.extend(expand_minimum(QUESTIONS))
